    private var closed = false

    /** Possible results returned */
    enum class Result(val value: Int) {
        /** Success */
        SUCCESS(0),
        /** Not available */
        NOT_AVAILABLE(1),
        /** Connection error */
        CONNECTION_ERROR(2),
        /** Unsupported */
        UNSUPPORTED(3),
        /** Denied */
        DENIED(4),
        /** Failed */
        FAILED(5),
        /** Timeout */
        TIMEOUT(6),
        /** No system */
        NO_SYSTEM(7),
        /** Not requested */
        NOT_REQUESTED(8);

        companion object {
            fun fromValue(value: Int): Result =
